questions.sql:
SELECT id, first_name, last_name
 FROM employees
 WHERE last_name LIKE 'J%';

SELECT last_name
 FROM employees
 WHERE last_name LIKE '_e%';

SELECT first_name
 FROM employees
 WHERE first_name LIKE 'T%e%';

SELECT id, first_name, last_name, city, notes
 FROM employees
 WHERE (
   city LIKE 'Washington'
   AND notes LIKE '%French%'
 ) OR (
   city LIKE 'Atlanta'
   AND (
    notes NOT LIKE '%French%'
    OR notes IS NULL
   )
 );

SELECT product_name, supplier_ids
 FROM products
 WHERE supplier_ids IN ('4','10');

SELECT product_name, supplier_ids
 FROM products
 WHERE supplier_ids NOT IN ('4','10');

SELECT product_name, list_price
 FROM products
 WHERE list_price BETWEEN 10 AND 20;

SELECT product_name, list_price
 FROM products
 WHERE list_price NOT BETWEEN 10 AND 20;

SELECT product_name, standard_cost, list_price
 FROM products
 WHERE list_price - standard_cost > 10;

SELECT id, product_name
 FROM products
 WHERE product_name LIKE '%soup%';

SELECT id, order_date, ship_city
 FROM orders
 WHERE shipping_fee>100 AND (payment_type='Check' OR order_date>='2006-03-01');

SELECT first_name, last_name, address, city
 FROM customers
 ORDER BY last_name, first_name, city DESC;

SELECT id, product_code, product_name
 FROM products
 WHERE list_price < 1.3 * standard_cost;

SELECT id, product_name
 FROM products
 WHERE supplier_ids LIKE '%;%';

SELECT id, product_name
 FROM products
 WHERE supplier_ids LIKE '%3%';

select i.*
from customers c join orders o on c.id = o.customer_id join invoices i on o.id = i.order_id 
where (c.city = 'Fresno' or c.city = 'Indianapolis') and i.invoice_date >= '2006-03-23';

SELECT product_name, list_price
 FROM products
 WHERE list_price BETWEEN 10 AND 20;

SELECT product_name, list_price
 FROM products
 WHERE list_price NOT BETWEEN 10 AND 20;

SELECT * 
FROM products
WHERE reorder_level <= 50;

select p.id, p.product_name, ceil(list_price), floor(standard_cost)
from products p 
where p.category = 'Soups';

select concat(left(c.first_name,2), left(c.last_name,2))
from customers c 
order by concat(left(c.first_name,2), left(c.last_name,2));

select upper(c.last_name), lower(c.first_name), replace(c.email_address,'.edu', '.cat') 
from customers c 
order by c.last_name, c.first_name;

select substr(p.product_name, 19)
from products p 
order by substr(p.product_name, 19);

select o.id, o.order_date, ifnull(o.shipped_date,'PENDENT') 
from orders o 
order by o.id;

select p.id, p.product_code, p.standard_cost, p.list_price, 
if(p.list_price-p.standard_cost >3,'MARGE ALT', 'MARGE NORMAL')
from products p

SELECT first_name , last_name , job_title 
FROM employees e 
ORDER BY last_name;

SELECT product_code , product_name , category 
FROM products
ORDER BY category;

SELECT first_name , last_name , city , company
FROM customers 
ORDER BY city , last_name ;

SELECT * 
FROM miniwind.customers
WHERE city = 'Santa Ana';

SELECT * 
FROM miniwind.products
WHERE list_price > 20;

SELECT * 
FROM miniwind.suppliers
WHERE last_name = 'Dunton';

SELECT * 
FROM miniwind.employees
WHERE job_title = 'Sales Coordinator';

SELECT * 
FROM miniwind.customers
WHERE city = 'Houston' OR city = 'Sacramento';

SELECT * 
FROM miniwind.products
WHERE list_price BETWEEN 50 AND 200;

SELECT * 
FROM miniwind.employees
WHERE job_title = 'Sales Representative' AND city = 'Washington';

SELECT e.first_name, e.last_name, o.id AS order_id, DATE(o.order_date) AS order_date
FROM miniwind.employees e
INNER JOIN miniwind.orders o ON e.id = o.employee_id;

SELECT o.id AS order_id, os.status_name, DATE(o.order_date) AS order_date
FROM miniwind.orders o
LEFT JOIN miniwind.orders_status os ON o.status_id = os.id;

SELECT e.first_name, e.last_name, o.id AS order_id
FROM miniwind.employees e 
LEFT JOIN miniwind.orders o ON o.employee_id = e.id;

SELECT c.first_name, c.last_name, o.id AS order_id, o.order_date
FROM miniwind.customers c
LEFT JOIN miniwind.orders o ON c.id = o.customer_id;

select p.*
from products p left join order_details od on p.id = od.product_id 
where od.product_id is null;

SELECT o.customer_id , COUNT(o.customer_id) as Pedidos
FROM orders o
GROUP BY o.customer_id;

SELECT c.id, COUNT(o.id)
FROM customers c left join orders o on c.id =o.customer_id
group by c.id;

SELECT product_name,
       ROUND(list_price * 0.9, 2) AS PreuAmbDescompte
FROM products;

SELECT distinct MONTH(order_date)
FROM orders
where order_date >='2006-01-01' and order_date <='2007-01-01';

SELECT count(*)
FROM orders
where order_date >='2006-01-01' and order_date <='2007-01-01';
